export const STATUS_DEFINITIONS={unconfirmed:{label:"Unconfirmed",color:"var(--text-muted)",description:"Awaiting evidence"},emerging:{label:"Emerging",color:"var(--signal-elevated)",description:"Early signals detected"},confirmed:{label:"Confirmed",color:"var(--signal-calm)",description:"Strong confirming evidence"},refuted:{label:"Refuted",color:"var(--signal-high)",description:"Contradicting evidence prevails"}};export function determineStatus(e){const{score:n,confidence:r,evidenceCount:i}=e;return i<3||"insufficient"===r?"unconfirmed":n>=50&&"low"!==r?"confirmed":n<=-50&&"low"!==r?"refuted":Math.abs(n)>=20?"emerging":"unconfirmed"}export function isValidTransition(e,n){return{unconfirmed:["emerging","confirmed","refuted"],emerging:["confirmed","refuted","unconfirmed"],confirmed:["refuted"],refuted:["confirmed"]}[e]?.includes(n)??!1}export function getStatusRecommendation(e,n){const r=e.status||"unconfirmed",i=determineStatus(n);return r===i?{change:!1,current:r,message:"Status is appropriate for current evidence"}:isValidTransition(r,i)?{change:!0,current:r,recommended:i,score:n.score,message:`Evidence suggests status change to ${i}`}:{change:!1,current:r,recommended:i,message:`Transition from ${r} to ${i} requires review`}}